<?php
namespace Pterodactyl\Services\Nodexa;
use Illuminate\Support\Facades\Crypt; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Http; use RuntimeException;
class FlaxVpsClient { private object $provider; public function __construct(?object $provider=null){$this->provider=$provider?:DB::table('vps_providers')->where('active',true)->first();if(!$this->provider)throw new RuntimeException('Flax VPS provider er ikke konfigureret.');} private function key():string{return Crypt::decryptString($this->provider->api_key);} public function request(string $action,array $params=[],string $method='POST'):array{$key=$this->key();$url=rtrim($this->provider->endpoint,'/').'/api-endpoint.php';$query=array_merge(['key'=>$key,'action'=>$action],$params);$http=Http::timeout(15)->acceptJson()->withToken($key)->withUserAgent('Nodexa-Flax-VPS/1.4');$response=strtoupper($method)==='GET'?$http->get($url,$query):$http->asForm()->post($url,$query);if(!$response->successful())throw new RuntimeException('Flax API HTTP '.$response->status());$json=$response->json();if(!is_array($json))throw new RuntimeException('Ugyldigt svar fra Flax API.');if(($json['status']??null)==='error')throw new RuntimeException((string)($json['data']??$json['message']??'Flax API fejl'));return is_array($json['data']??null)?$json['data']:$json;} private function list(array $r,array $keys):array{foreach($keys as $k)if(isset($r[$k])&&is_array($r[$k]))return array_values($r[$k]);return array_is_list($r)?$r:[];} public function servers():array{return $this->list($this->request('user_servers',[],'GET'),['servers','data','result']);}
private function fallbackProducts():array{return [
['id'=>1,'productId'=>1,'name'=>'VPS-01','price'=>69.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>2,'productId'=>2,'name'=>'VPS-02','price'=>109.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>3,'productId'=>3,'name'=>'VPS-03','price'=>149.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>4,'productId'=>4,'name'=>'VPS-04','price'=>199.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>5,'productId'=>5,'name'=>'VPS-05','price'=>259.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>6,'productId'=>6,'name'=>'VPS-06','price'=>319.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>7,'productId'=>7,'name'=>'VPS-01+','price'=>99.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>8,'productId'=>8,'name'=>'VPS-02+','price'=>129.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>9,'productId'=>9,'name'=>'VPS-03+','price'=>189.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>10,'productId'=>10,'name'=>'VPS-04+','price'=>219.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>11,'productId'=>11,'name'=>'VPS-05+','price'=>339.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>12,'productId'=>12,'name'=>'VPS-06+','price'=>469.00,'currency'=>'DKK','type'=>'VIRTUSION']];}
public function discoverProducts():array{foreach(['products','packages','plans','vps_products','list_products'] as $a){try{$x=$this->list($this->request($a,[],'GET'),['products','packages','plans','data','result']);if($x)return $x;}catch(\Throwable $e){}}return $this->fallbackProducts();}
private function normalizeOsList(array $raw):array{$out=[];$walk=function($value,$key=null)use(&$walk,&$out){if(is_array($value)){if(isset($value['id'])||isset($value['template_id'])||isset($value['osid'])||isset($value['os_id'])){$id=(string)($value['id']??$value['template_id']??$value['osid']??$value['os_id']);$name=(string)($value['name']??$value['title']??$value['os_name']??$value['label']??$value['filename']??$id);if($id!=='')$out[$id]=['id'=>$id,'value'=>$id,'template_id'=>$id,'name'=>$name,'label'=>$name]+$value;return;}foreach($value as $k=>$v){if(!is_array($v)&&is_numeric($k)){continue;}if(!is_array($v)&&preg_match('/^\d+$/',(string)$k)){$id=(string)$k;$name=(string)$v;$out[$id]=['id'=>$id,'value'=>$id,'template_id'=>$id,'name'=>$name,'label'=>$name];}else{$walk($v,$k);}}}};$walk($raw);return array_values($out);}
public function discoverOperatingSystems(?string $product=null):array{try{$raw=$this->request('virtualizor_templates',[],'GET');$x=$this->normalizeOsList($raw);if($x)return $x;}catch(\Throwable $e){}foreach(['operating_systems','os_templates','templates','oses'] as $a){try{$p=$product?['productId'=>$product]:[];$raw=$this->request($a,$p,'GET');$x=$this->normalizeOsList($raw);if(!$x)$x=$this->list($raw,['templates','virtualizor_templates','operatingSystems','operating_systems','oses','data','result']);if($x)return $x;}catch(\Throwable $e){}}return [];}
public function virtualizorTemplates():array{$raw=$this->request('virtualizor_templates',[],'GET');$x=$this->normalizeOsList($raw);return $x?:$this->list($raw,['templates','virtualizor_templates','data','result']);} public function wispEggs():array{return $this->list($this->request('wisp-eggs',[],'GET'),['eggs','wisp_eggs','data','result']);} public function info(string $id):array{return $this->request('info',['server_id'=>$id],'GET');} public function power(string $id,string $action):array{if(!in_array($action,['boot','shutdown','restart','poweroff'],true))throw new RuntimeException('Ugyldig VPS handling.');return $this->request($action,['server_id'=>$id]);} public function os(string $id):array{return $this->request('os_info',['server_id'=>$id],'GET');} public function rebuild(string $id,string $os):array{return $this->request('build',['server_id'=>$id,'operatingSystem'=>$os]);} public function create(string $productId,string $osId,?string $gameType=null):array{$params=['productId'=>$productId,'operatingSystem'=>$osId];if($gameType!==null&&$gameType!=='')$params['gameType']=$gameType;return $this->request('create',$params);}}
